            const { motivo, valorMinimo } = resultado;
            const corpoErro = { aceito: false, motivo, ...(valorMinimo === undefined ? {} : { valorMinimo }) };
            if (motivo === 'LEILAO_ENCERRADO') throw new ConflictException(corpoErro);
